1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create request whose last name and address already belong to another owner, comparing
11	 * both case-insensitively with collapsed whitespace. A request that opts in with
12	 * {@code sharesHousehold=true} is allowed through. Responds 409 on a clash.
13	 */
14	public class RejectDuplicateHousehold {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateHouseholdException {
18	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
19	            return;
20	        }
21	        String lastName = normalize(request.getLastName());
22	        String address = normalize(request.getAddress());
23	        for (Owner owner : ownerRepository.findAll()) {
24	            if (lastName.equals(normalize(owner.getLastName()))
25	                    && address.equals(normalize(owner.getAddress()))) {
26	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
27	            }
28	        }
29	    }
30	
31	    private static String normalize(String value) {
32	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
33	    }
34	}
