15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
23	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
24	    @Mapping(target = "membershipLevel", expression = "java(Math.min(3, 1 + (owner.getEmail() != null && !owner.getEmail().isEmpty() ? 1 : 0) + (Integer.valueOf(0).equals(owner.getNamesakeCount()) ? 1 : 0)))")
25	    @Mapping(target = "locality", expression = "java(\"Sydney\".equals(owner.getCity()) ? \"NSW\" : \"Melbourne\".equals(owner.getCity()) ? \"VIC\" : \"Brisbane\".equals(owner.getCity()) ? \"QLD\" : \"UNKNOWN\")")
26	    @Mapping(target = "contactPreference", expression = "java(owner.getEmail() != null && !owner.getEmail().isEmpty() ? \"EMAIL\" : \"PHONE\")")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    Owner toOwner(OwnerDto ownerDto);
30	
31	    @Mapping(target = "id", ignore = true)
32	    @Mapping(target = "pets", ignore = true)
33	    Owner toOwner(OwnerFieldsDto ownerDto);
34	
35	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
36	
37	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
38	
39	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
40	        OwnerPageDto ownerPageDto = new OwnerPageDto();
41	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
42	        ownerPageDto.setPage(ownerPage.getNumber());
43	        ownerPageDto.setSize(ownerPage.getSize());
44	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
45	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
46	        return ownerPageDto;
47	    }
48	}
