1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
6	
7	/**
8	 * Upgrades an owner's membership tier to {@code GOLD} when their household (owners sharing the same
9	 * {@code householdId}) has three or more members. Applied after the base BRONZE/SILVER tier has been
10	 * mapped, so GOLD takes precedence; owners without a household are left untouched.
11	 */
12	final class HouseholdTier {
13	
14	    private HouseholdTier() {
15	    }
16	
17	    static void applyGold(Owner owner, OwnerRepository ownerRepository, OwnerDto dto) {
18	        String householdId = owner.getHouseholdId();
19	        if (householdId == null) {
20	            return;
21	        }
22	        int members = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (householdId.equals(existing.getHouseholdId())) {
25	                members++;
26	            }
27	        }
28	        if (members >= 3) {
29	            dto.setMembershipLevel(3);
30	        }
31	    }
32	}
