===== Owner schema in openapi =====
    Owner:
      title: Owner
      description: A pet owner.
      allOf:
        - $ref: '#/components/schemas/OwnerFields'
        - type: object
          properties:
            id:
              title: ID
              description: The ID of the pet owner.
              type: integer
              format: int32
              minimum: 0
              example: 1
              readOnly: true
            displayName:
              title: Display name
              description: The owner's name formatted as 'LastName, FirstName'.
              type: string
              example: "Franklin, George"
              readOnly: true
            initials:
              title: Initials
              description: The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot.
              type: string
              example: "G.F."
              readOnly: true
            customerCode:
              title: Customer code
              description: "The owner's customer code, formatted '<LAST3>-<NNNN>': the upper-cased first three letters of lastName and a global 4-digit zero-padded sequence."
              type: string
              example: "FRA-0007"
              readOnly: true
            householdId:
              title: Household ID
              description: "A stable shared identifier assigned when an owner joins an existing same-lastName household at the same address via sharesHousehold; every member shares one value."
              type: string
              example: "HH-1A2B3C4D"
              readOnly: true
            namesakeCount:
              title: Namesake count
              description: "The number of existing owners that shared this owner's firstName and lastName (case-insensitively) at the moment it was created."
              type: integer
              format: int32
              minimum: 0
              example: 1
              readOnly: true
            membershipNumber:
              title: Membership number
              description: "The owner's membership number, formatted '<customerCode>-M<YY>' where YY is the last two digits of the registrationDate year."
              type: string
              example: "SMI-0007-M26"
              readOnly: true
            membershipLevel:
              title: Membership level
              description: "Numeric level from 1 to 3: starts at 1, +1 when an email is present, +1 when namesakeCount is 0, capped at 3 (level 4 is reserved for tenure)."
              type: integer
              format: int32
              minimum: 1
              maximum: 3
              example: 3
              readOnly: true
            locality:
              title: Locality
              description: "The canonical region derived from city (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or 'UNKNOWN' when the city is not in the table."
              type: string
              example: "NSW"
              readOnly: true
            bulkSignupWarning:
